import java.io.*;
import java.util.*;

public class Main {
    static int nx, ny;
    static int[] xs, ys;
    static short[] coverage;
    static long[] horizontalDegenerate;
    static long[] verticalDegenerate;

    static long[] dist;
    static IndexedHeap heap;

    static void setBit(long[] bits, int index) {
        bits[index >>> 6] |= 1L << (index & 63);
    }

    static boolean isSet(long[] bits, int index) {
        return (bits[index >>> 6] & (1L << (index & 63))) != 0;
    }

    static boolean horizontalCovered(int xIndex, int yIndex) {
        int edgeIndex = yIndex * (nx - 1) + xIndex;

        if (isSet(horizontalDegenerate, edgeIndex)) {
            return true;
        }

        // Célula imediatamente abaixo da aresta.
        if (yIndex > 0 && coverage[(yIndex - 1) * nx + xIndex] > 0) {
            return true;
        }

        // Célula imediatamente acima da aresta.
        return yIndex < ny - 1 && coverage[yIndex * nx + xIndex] > 0;
    }

    static boolean verticalCovered(int xIndex, int yIndex) {
        int edgeIndex = yIndex * nx + xIndex;

        if (isSet(verticalDegenerate, edgeIndex)) {
            return true;
        }

        // Célula imediatamente à esquerda da aresta.
        if (xIndex > 0 && coverage[yIndex * nx + (xIndex - 1)] > 0) {
            return true;
        }

        // Célula imediatamente à direita da aresta.
        return xIndex < nx - 1 && coverage[yIndex * nx + xIndex] > 0;
    }

    static void relax(int vertex, long newDistance) {
        if (newDistance >= dist[vertex] || heap.position[vertex] == -2) {
            return;
        }

        dist[vertex] = newDistance;
        heap.addOrDecrease(vertex);
    }

    static int[] sortedUnique(int[] values) {
        Arrays.sort(values);
        int size = 0;

        for (int value : values) {
            if (size == 0 || values[size - 1] != value) {
                values[size++] = value;
            }
        }

        return Arrays.copyOf(values, size);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int xi = fs.nextInt();
        int yi = fs.nextInt();
        int xf = fs.nextInt();
        int yf = fs.nextInt();

        int n = fs.nextInt();
        int[][] rectangles = new int[n][4];

        int[] allX = new int[2 + 2 * n];
        int[] allY = new int[2 + 2 * n];

        allX[0] = xi;
        allX[1] = xf;
        allY[0] = yi;
        allY[1] = yf;

        for (int i = 0; i < n; i++) {
            int x1 = fs.nextInt();
            int y1 = fs.nextInt();
            int x2 = fs.nextInt();
            int y2 = fs.nextInt();

            rectangles[i][0] = x1;
            rectangles[i][1] = y1;
            rectangles[i][2] = x2;
            rectangles[i][3] = y2;

            allX[2 + 2 * i] = x1;
            allX[3 + 2 * i] = x2;
            allY[2 + 2 * i] = y1;
            allY[3 + 2 * i] = y2;
        }

        xs = sortedUnique(allX);
        ys = sortedUnique(allY);
        nx = xs.length;
        ny = ys.length;

        int gridSize = nx * ny;
        coverage = new short[gridSize];

        horizontalDegenerate = new long[((ny * (nx - 1)) + 63) >>> 6];
        verticalDegenerate = new long[(((ny - 1) * nx) + 63) >>> 6];

        for (int[] rectangle : rectangles) {
            int x1 = Arrays.binarySearch(xs, rectangle[0]);
            int y1 = Arrays.binarySearch(ys, rectangle[1]);
            int x2 = Arrays.binarySearch(xs, rectangle[2]);
            int y2 = Arrays.binarySearch(ys, rectangle[3]);

            if (x1 < x2 && y1 < y2) {
                // Atualização de retângulo na matriz de diferenças.
                coverage[y1 * nx + x1]++;
                coverage[y1 * nx + x2]--;
                coverage[y2 * nx + x1]--;
                coverage[y2 * nx + x2]++;
            } else if (x1 == x2 && y1 < y2) {
                // Retângulo degenerado: segmento vertical.
                for (int y = y1; y < y2; y++) {
                    setBit(verticalDegenerate, y * nx + x1);
                }
            } else if (y1 == y2 && x1 < x2) {
                // Retângulo degenerado: segmento horizontal.
                for (int x = x1; x < x2; x++) {
                    setBit(horizontalDegenerate, y1 * (nx - 1) + x);
                }
            }
            // Um retângulo degenerado em um único ponto não cobre arestas.
        }

        // Converte a matriz de diferenças em contagem de cobertura por célula.
        for (int y = 0; y < ny; y++) {
            for (int x = 0; x < nx; x++) {
                int index = y * nx + x;
                int value = coverage[index];

                if (y > 0) {
                    value += coverage[index - nx];
                }
                if (x > 0) {
                    value += coverage[index - 1];
                }
                if (x > 0 && y > 0) {
                    value -= coverage[index - nx - 1];
                }

                coverage[index] = (short) value;
            }
        }

        int startX = Arrays.binarySearch(xs, xi);
        int startY = Arrays.binarySearch(ys, yi);
        int endX = Arrays.binarySearch(xs, xf);
        int endY = Arrays.binarySearch(ys, yf);

        int start = startY * nx + startX;
        int target = endY * nx + endX;

        dist = new long[gridSize];
        Arrays.fill(dist, Long.MAX_VALUE);

        heap = new IndexedHeap(gridSize, dist);
        dist[start] = 0;
        heap.addOrDecrease(start);

        while (!heap.isEmpty()) {
            int vertex = heap.removeMin();
            if (vertex == target) {
                break;
            }

            int y = vertex / nx;
            int x = vertex - y * nx;
            long currentDistance = dist[vertex];

            if (x > 0) {
                long cost = horizontalCovered(x - 1, y) ? 0 : xs[x] - xs[x - 1];
                relax(vertex - 1, currentDistance + cost);
            }

            if (x + 1 < nx) {
                long cost = horizontalCovered(x, y) ? 0 : xs[x + 1] - xs[x];
                relax(vertex + 1, currentDistance + cost);
            }

            if (y > 0) {
                long cost = verticalCovered(x, y - 1) ? 0 : ys[y] - ys[y - 1];
                relax(vertex - nx, currentDistance + cost);
            }

            if (y + 1 < ny) {
                long cost = verticalCovered(x, y) ? 0 : ys[y + 1] - ys[y];
                relax(vertex + nx, currentDistance + cost);
            }
        }

        System.out.println(dist[target]);
    }

    static class IndexedHeap {
        final int[] heap;
        final int[] position;
        final long[] distances;
        int size;

        IndexedHeap(int capacity, long[] distances) {
            this.heap = new int[capacity];
            this.position = new int[capacity];
            Arrays.fill(position, -1);
            this.distances = distances;
        }

        boolean isEmpty() {
            return size == 0;
        }

        void addOrDecrease(int vertex) {
            int index = position[vertex];

            if (index == -1) {
                index = size++;
                heap[index] = vertex;
                position[vertex] = index;
            }

            siftUp(index);
        }

        int removeMin() {
            int result = heap[0];
            position[result] = -2;

            int last = heap[--size];
            if (size > 0) {
                heap[0] = last;
                position[last] = 0;
                siftDown(0);
            }

            return result;
        }

        void siftUp(int index) {
            while (index > 0) {
                int parent = (index - 1) >>> 1;
                if (distances[heap[parent]] <= distances[heap[index]]) {
                    break;
                }
                swap(index, parent);
                index = parent;
            }
        }

        void siftDown(int index) {
            while (true) {
                int left = index * 2 + 1;
                if (left >= size) {
                    break;
                }

                int right = left + 1;
                int smallest = left;

                if (right < size &&
                    distances[heap[right]] < distances[heap[left]]) {
                    smallest = right;
                }

                if (distances[heap[index]] <= distances[heap[smallest]]) {
                    break;
                }

                swap(index, smallest);
                index = smallest;
            }
        }

        void swap(int a, int b) {
            int temp = heap[a];
            heap[a] = heap[b];
            heap[b] = temp;
            position[heap[a]] = a;
            position[heap[b]] = b;
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}
